'use strict';
// Shared local audio player. The bundled speech fixture is not a user recording.
const aiVoicePlayers=new Map();let aiVoiceSequence=0,aiVoiceActiveSession='';
const aiVoiceSample={src:'assets/voice-subscription-preview.wav',duration:7.7864399093,peaks:[72, 64, 72, 73, 66, 69, 73, 56, 76, 67, 55, 71, 63, 60, 57, 69, 71, 78, 12, 78, 56, 41, 62, 58, 68, 65, 59, 64, 63, 67, 66, 61, 12, 55, 52, 60, 55, 73, 20, 12],transcript:'I pay USD 9.99 monthly for Duolingo. My next renewal is 20 November 2026.'};
function aiVoiceMetadata(key){return {key,src:aiVoiceSample.src,duration:aiVoiceSample.duration,peaks:[...aiVoiceSample.peaks]};}
function aiVoiceTime(seconds,roundUp=false){const total=Math.max(0,roundUp?Math.ceil(Number(seconds)||0):Math.floor(Number(seconds)||0));return Math.floor(total/60)+':'+String(total%60).padStart(2,'0');}
function aiVoiceProgress(currentTime,duration){return Number.isFinite(duration)&&duration>0?Math.max(0,Math.min(100,currentTime/duration*100)):0;}
function aiVoicePlayIcon(paused){return `<svg viewBox="0 0 24 24" aria-hidden="true">${paused?'<path d="M8 5 19 12 8 19Z"/>':'<rect x="7" y="5" width="3.5" height="14" rx="1"/><rect x="14" y="5" width="3.5" height="14" rx="1"/>'}</svg>`;}
function aiVoiceMessage(meta){const entry=aiVoicePlayers.get(meta.key),audio=entry?.audio,duration=Number.isFinite(audio?.duration)&&audio.duration>0?audio.duration:meta.duration,time=audio?.currentTime||0,paused=!audio||audio.paused;const bars=meta.peaks.map(height=>`<i style="height:${Math.max(12,Math.min(100,height))}%"></i>`).join('');return `<div class="ai-voice-player" data-ai-voice-id="${escape(meta.key)}" style="--voice-progress:${aiVoiceProgress(time,duration)}%"><button type="button" class="ai-voice-play" data-ai-voice-toggle="${escape(meta.key)}" aria-label="${paused?'Play':'Pause'} voice message" aria-pressed="${!paused}">${aiVoicePlayIcon(paused)}</button><div class="ai-voice-track"><div class="ai-voice-wave"><span class="ai-voice-wave-base" aria-hidden="true">${bars}</span><span class="ai-voice-wave-played" aria-hidden="true">${bars}</span><input type="range" class="ai-voice-seek" data-ai-voice-seek="${escape(meta.key)}" min="0" max="${duration}" step="0.1" value="${time}" aria-label="Seek voice message" aria-valuetext="${aiVoiceTime(time)} of ${aiVoiceTime(duration,true)}"></div><div class="ai-voice-caption"><span>Voice message</span><span data-ai-voice-time>${aiVoiceTime(time)} / ${aiVoiceTime(duration,true)}</span></div><span class="ai-voice-error" hidden>Audio unavailable. Try again.</span></div></div>`;}
function aiVoiceEntry(meta){let entry=aiVoicePlayers.get(meta.key);if(entry)return entry;const audio=new Audio(meta.src);audio.preload='metadata';entry={audio,meta,error:false,blobUrl:''};aiVoicePlayers.set(meta.key,entry);entry.ready=fetch(meta.src).then(response=>{if(!response.ok)throw new Error('Audio unavailable');return response.blob();}).then(blob=>{if(aiVoicePlayers.get(meta.key)!==entry)return;entry.blobUrl=URL.createObjectURL(blob);audio.src=entry.blobUrl;audio.load();}).catch(()=>{});for(const name of ['loadedmetadata','durationchange','timeupdate','seeked','play','pause','ended'])audio.addEventListener(name,()=>aiVoicePaint(meta.key));audio.addEventListener('error',()=>{entry.error=true;aiVoicePaint(meta.key);});return entry;}
function aiVoicePaint(key){const entry=aiVoicePlayers.get(key);if(!entry)return;const audio=entry.audio,duration=Number.isFinite(audio.duration)&&audio.duration>0?audio.duration:entry.meta.duration;for(const view of document.querySelectorAll('[data-ai-voice-id]')){if(view.dataset.aiVoiceId!==key)continue;view.style.setProperty('--voice-progress',aiVoiceProgress(audio.currentTime,duration)+'%');const play=view.querySelector('[data-ai-voice-toggle]');play.innerHTML=aiVoicePlayIcon(audio.paused);play.setAttribute('aria-label',(audio.paused?'Play':'Pause')+' voice message');play.setAttribute('aria-pressed',String(!audio.paused));const seek=view.querySelector('[data-ai-voice-seek]');seek.max=duration;seek.value=audio.currentTime;seek.setAttribute('aria-valuetext',aiVoiceTime(audio.currentTime)+' of '+aiVoiceTime(duration,true));view.querySelector('[data-ai-voice-time]').textContent=aiVoiceTime(audio.ended?duration:audio.currentTime,audio.ended)+' / '+aiVoiceTime(duration,true);view.querySelector('.ai-voice-error').hidden=!entry.error;}}
function initAiVoicePlayers(session){const metadata=[...session.messages.filter(m=>m.kind==='voice').map(m=>m.audio),...(session.voiceDraft?[session.voiceDraft]:[])];metadata.forEach(meta=>{aiVoiceEntry(meta);aiVoicePaint(meta.key);});if(aiVoiceActiveSession&&aiVoiceActiveSession!==aiTextKey())pauseAiVoicePlayers();aiVoiceActiveSession=aiTextKey();}
function pauseAiVoicePlayers(){for(const entry of aiVoicePlayers.values())entry.audio.pause();}
function clearAiVoicePlayers(){pauseAiVoicePlayers();for(const entry of aiVoicePlayers.values()){entry.audio.removeAttribute('src');entry.audio.load();if(entry.blobUrl)URL.revokeObjectURL(entry.blobUrl);if(entry.meta.ownedUrl)URL.revokeObjectURL(entry.meta.src);}aiVoicePlayers.clear();aiVoiceActiveSession='';}
function aiRefreshComposer(session){pauseAiVoicePlayers();const footer=document.querySelector('.ai-text-composer');if(footer)footer.outerHTML=aiChatComposer(session);aiSyncComposer();initAiVoicePlayers(session);}
function syncAiVoiceComposer(session){const shell=document.querySelector('.ai-chat-shell'),footer=document.querySelector('.ai-text-composer');if(shell&&footer)shell.style.setProperty('--ai-composer-height',footer.offsetHeight+'px');}
document.addEventListener('click',async e=>{const play=e.target.closest('[data-ai-voice-toggle]');if(!play)return;const entry=aiVoicePlayers.get(play.dataset.aiVoiceToggle);if(!entry)return;if(!entry.audio.paused){entry.audio.pause();return;}pauseAiVoicePlayers();if(entry.error){entry.error=false;entry.audio.load();}if(entry.audio.ended)entry.audio.currentTime=0;try{await entry.ready;await entry.audio.play();}catch{entry.error=true;aiVoicePaint(entry.meta.key);toast('Unable to play this voice message. Please try again.');}});
function seekAiVoiceMessage(e){if(!e.target.matches('[data-ai-voice-seek]'))return;const entry=aiVoicePlayers.get(e.target.dataset.aiVoiceSeek);if(entry&&Number.isFinite(entry.audio.duration)&&entry.audio.duration>0){entry.audio.currentTime=Math.max(0,Math.min(entry.audio.duration,Number(e.target.value)));}}
document.addEventListener('input',seekAiVoiceMessage);document.addEventListener('change',seekAiVoiceMessage);
function disposeAiVoiceSession(session){const keys=[...session.messages.filter(m=>m.kind==='voice').map(m=>m.audio.key),...(session.voiceDraft?[session.voiceDraft.key]:[])];for(const key of keys){const entry=aiVoicePlayers.get(key);if(entry){entry.audio.pause();entry.audio.removeAttribute('src');entry.audio.load();if(entry.blobUrl)URL.revokeObjectURL(entry.blobUrl);if(entry.meta.ownedUrl)URL.revokeObjectURL(entry.meta.src);aiVoicePlayers.delete(key);}}}

// Recording-state simulation; never requests or captures the microphone.
let aiRecordingClock=null,aiRecordingSampleBuffer=null,aiRecordingSession=null;
function aiRecordingElapsed(recording,now=Date.now()){return Math.max(0,recording.elapsedMs+(recording.paused?0:now-recording.startedAt));}
function aiRecordingComposer(session){const r=session.voiceRecording;return `<div class="ai-text-composer ai-recording-composer"><div class="ai-recording-box ${r.preparing?'is-paused':''} ${r.cancelRequested?'is-cancelling':''}"><div class="ai-recording-heading"><span role="status"><i aria-hidden="true"></i>${r.preparing?'Sending voice message…':'Recording'}</span><time data-ai-recording-time>${aiVoiceTime(aiRecordingElapsed(r)/1000)}</time></div><div class="ai-recording-wave" aria-hidden="true">${aiVoiceSample.peaks.map((n,i)=>`<i style="height:${Math.max(18,n)}%;animation-delay:-${i*.073}s"></i>`).join('')}</div><div class="ai-hold-actions"><span class="ai-hold-hint" data-ai-hold-hint>${r.preparing?'Preparing your message…':r.cancelRequested?'Release to cancel':'‹ Slide left to cancel'}<small>${r.preparing?'':r.cancelRequested?'This recording won’t be sent.':'Release to send'}</small></span><span class="ai-held-mic" aria-hidden="true">${aiTextIcon('voice')}</span></div></div></div>`;}
function cancelAiVoiceRecording(session=aiRecordingSession){const target=session||aiRecordingSession;if(!aiRecordingSession||target===aiRecordingSession){clearInterval(aiRecordingClock);aiRecordingClock=null;aiRecordingSession=null;}if(target)target.voiceRecording=null;if(aiHoldGesture?.session===target)releaseAiHoldCapture();}
function syncAiRecordingContext(session){if(aiRecordingSession&&aiRecordingSession!==session)cancelAiVoiceRecording(aiRecordingSession);}
function startAiVoiceRecording(){const session=aiTextSession();if(session.thinking||session.saving||session.messages.some(m=>m.failed)||session.voiceRecording)return false;syncAiRecordingContext(session);aiRecordingSession=session;pauseAiVoicePlayers();session.voiceDraft=null;session.voiceRecording={elapsedMs:0,startedAt:Date.now(),paused:false,preparing:false};if(!aiRecordingSampleBuffer)aiRecordingSampleBuffer=fetch(aiVoiceSample.src).then(r=>{if(!r.ok)throw new Error('Sample unavailable');return r.arrayBuffer();}).catch(error=>{aiRecordingSampleBuffer=null;throw error;});aiRecordingSampleBuffer.catch(()=>{});aiRefreshComposer(session);aiRefreshConversation(session);clearInterval(aiRecordingClock);aiRecordingClock=setInterval(()=>{const recording=session.voiceRecording;if(!recording||recording.preparing||!isAiChatScreen()||aiTextSession()!==session){cancelAiVoiceRecording(session);return;}const elapsed=aiRecordingElapsed(recording);const time=document.querySelector('[data-ai-recording-time]');if(time)time.textContent=aiVoiceTime(elapsed/1000);},100);return true;}
function aiClipWaveBuffer(buffer,seconds){const view=new DataView(buffer);if(view.getUint32(0,false)!==0x52494646||view.getUint32(8,false)!==0x57415645)throw new Error('Unsupported sample');let rate=0,alignment=0,channels=0,bits=0,dataOffset=0,dataSize=0,sizeOffset=0;for(let p=12;p+8<=view.byteLength;){const kind=view.getUint32(p,false),size=view.getUint32(p+4,true);if(p+8+size>view.byteLength)throw new Error('Invalid sample');if(kind===0x666d7420){if(view.getUint16(p+8,true)!==1)throw new Error('Unsupported sample');channels=view.getUint16(p+10,true);rate=view.getUint32(p+12,true);alignment=view.getUint16(p+20,true);bits=view.getUint16(p+22,true);}if(kind===0x64617461){dataOffset=p+8;dataSize=size;sizeOffset=p+4;break;}p+=8+size+(size%2);}if(!rate||!alignment||bits!==16||!channels||!dataOffset)throw new Error('Invalid sample');const frames=Math.min(Math.floor(dataSize/alignment),Math.max(1,Math.floor(Math.max(.25,seconds)*rate))),length=frames*alignment,out=buffer.slice(0,dataOffset+length),outView=new DataView(out);outView.setUint32(4,out.byteLength-8,true);outView.setUint32(sizeOffset,length,true);const peaks=Array.from({length:40},(_,i)=>{let peak=0;const start=Math.floor(i*frames/40),end=Math.max(start+1,Math.floor((i+1)*frames/40));for(let f=start;f<Math.min(frames,end);f++){peak=Math.max(peak,Math.abs(outView.getInt16(dataOffset+f*alignment,true)));}return Math.max(12,Math.round(peak/32768*100));});return {buffer:out,duration:frames/rate,peaks};}
async function stopAiVoiceRecording(session=aiTextSession()){const recording=session.voiceRecording;if(!recording||recording.preparing)return;recording.elapsedMs=aiRecordingElapsed(recording);recording.paused=true;recording.preparing=true;clearInterval(aiRecordingClock);aiRecordingClock=null;aiRefreshComposer(session);try{const buffer=await aiRecordingSampleBuffer;if(session.voiceRecording!==recording)return;const clip=aiHoldWaveBuffer(buffer,recording.elapsedMs/1000),meta={key:'voice-recording-'+(++aiVoiceSequence),src:URL.createObjectURL(new Blob([clip.buffer],{type:'audio/wav'})),duration:clip.duration,peaks:clip.peaks,ownedUrl:true};session.voiceRecording=null;if(aiRecordingSession===session)aiRecordingSession=null;if(isAiChatScreen()&&aiTextSession()===session){aiRefreshComposer(session);aiSendText(aiVoiceSample.transcript,undefined,meta);}else URL.revokeObjectURL(meta.src);}catch{if(session.voiceRecording!==recording)return;session.voiceRecording=null;if(aiRecordingSession===session)aiRecordingSession=null;aiRefreshComposer(session);aiRefreshConversation(session);toast('Unable to send this voice message. Please try again.');}}

// Hold gesture owns capture on the stable phone element, not the replaced composer button.
let aiHoldGesture=null;
function aiHoldOutcome(elapsedMs,deltaX=0,cancelled=false){return cancelled||deltaX<=-72||elapsedMs<300?'cancel':'send';}
function releaseAiHoldCapture(){const hold=aiHoldGesture;aiHoldGesture=null;if(hold?.phone&&hold.pointerId!==null){try{if(hold.phone.hasPointerCapture(hold.pointerId))hold.phone.releasePointerCapture(hold.pointerId);}catch{}}return hold;}
function beginAiVoiceHold(target,pointerId,x,kind){const session=aiTextSession();if(aiHoldGesture||session.thinking||session.saving||session.messages.some(m=>m.failed))return;const phone=target.closest('.phone');aiHoldGesture={session,phone,pointerId,startX:x,deltaX:0,cancelled:false,kind};if(pointerId!==null){try{phone.setPointerCapture(pointerId);}catch{}}if(!startAiVoiceRecording())releaseAiHoldCapture();}
function endAiVoiceHold(forceCancel=false){const hold=releaseAiHoldCapture();if(!hold)return;const r=hold.session.voiceRecording;if(!r)return;const elapsed=aiRecordingElapsed(r),outcome=aiHoldOutcome(elapsed,hold.deltaX,forceCancel||hold.cancelled);if(outcome==='cancel'){cancelAiVoiceRecording(hold.session);if(isAiChatScreen()&&aiTextSession()===hold.session){aiRefreshComposer(hold.session);aiRefreshConversation(hold.session);if(!forceCancel&&elapsed<300)toast('Hold the microphone to record. Release to send.');}}else stopAiVoiceRecording(hold.session);}
document.addEventListener('pointerdown',e=>{const mic=e.target.closest('[data-ai-hold-mic]');if(!mic||e.button!==0||mic.disabled)return;e.preventDefault();beginAiVoiceHold(mic,e.pointerId,e.clientX,'pointer');},{passive:false});
document.addEventListener('pointermove',e=>{const hold=aiHoldGesture;if(!hold||hold.kind!=='pointer'||hold.pointerId!==e.pointerId)return;e.preventDefault();hold.deltaX=e.clientX-hold.startX;if(hold.deltaX<=-72)hold.cancelled=true;const r=hold.session.voiceRecording;if(!r)return;r.cancelRequested=hold.cancelled;const box=document.querySelector('.ai-recording-box'),hint=document.querySelector('[data-ai-hold-hint]');box?.classList.toggle('is-cancelling',hold.cancelled);if(hint)hint.innerHTML=hold.cancelled?'Release to cancel<small>This recording won’t be sent.</small>':'‹ Slide left to cancel<small>Release to send</small>';},{passive:false});
document.addEventListener('pointerup',e=>{if(aiHoldGesture?.pointerId===e.pointerId)endAiVoiceHold();});
for(const eventName of ['pointercancel','lostpointercapture'])document.addEventListener(eventName,e=>{if(aiHoldGesture?.pointerId===e.pointerId)endAiVoiceHold(true);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&aiHoldGesture){e.preventDefault();endAiVoiceHold(true);return;}const mic=e.target.closest('[data-ai-hold-mic]');if(!mic||![' ','Enter'].includes(e.key)||e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.isComposing)return;e.preventDefault();beginAiVoiceHold(mic,null,0,'keyboard');});
document.addEventListener('keyup',e=>{if(aiHoldGesture?.kind==='keyboard'&&[' ','Enter'].includes(e.key)){e.preventDefault();endAiVoiceHold();}});
document.addEventListener('contextmenu',e=>{if(aiHoldGesture||e.target.closest('[data-ai-hold-mic]'))e.preventDefault();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)endAiVoiceHold(true);});
if(typeof window!=='undefined')window.addEventListener('blur',()=>endAiVoiceHold(true));
function aiHoldWaveBuffer(buffer,seconds){const sample=aiClipWaveBuffer(buffer,Infinity);if(seconds<=sample.duration)return aiClipWaveBuffer(buffer,seconds);const input=new DataView(buffer);let rate=0,align=0,offset=0,size=0,sizeOffset=0;for(let p=12;p+8<=input.byteLength;){const kind=input.getUint32(p,false),n=input.getUint32(p+4,true);if(kind===0x666d7420){rate=input.getUint32(p+12,true);align=input.getUint16(p+20,true);}if(kind===0x64617461){offset=p+8;size=n;sizeOffset=p+4;break;}p+=8+n+(n%2);}const frames=Math.ceil(seconds*rate),bytes=frames*align;if(!Number.isFinite(bytes)||bytes>64*1024*1024)throw new Error('Preview clip too long');const out=new Uint8Array(offset+bytes);out.set(new Uint8Array(buffer,0,offset));const data=new Uint8Array(buffer,offset,size);for(let p=offset;p<out.length;p+=data.length)out.set(data.subarray(0,Math.min(data.length,out.length-p)),p);const view=new DataView(out.buffer);view.setUint32(4,out.length-8,true);view.setUint32(sizeOffset,bytes,true);return aiClipWaveBuffer(out.buffer,seconds);}
